/bin/zsh -lc "Rscript --vanilla -e '
paths <- c(v1 = \"/Users/manoelgaldino/Documents/DCP/Papers/RDD Trade/red_trade/reports/refine_ink_review_paper_v4_2026-09-14/execution/candidate_v1.Rmd\", v2 = \"/private/tmp/refine-review-20260914/candidate_v2.Rmd\")
docs <- lapply(paths, readLines, warn = FALSE, encoding = \"UTF-8\")
extract_chunks <- function(lines) {
  starts <- grep(\""'^'"\\"'`'"\\"'`'"\\"'`'"\\\\{r(?:[ ,}])\", lines, perl = TRUE)
  labels <- character(length(starts))
  for (i in seq_along(starts)) {
    s <- starts[[i]]
    rel_end <- which(lines[seq.int(s + 1L, length(lines))] == \""'```")
    if (!length(rel_end)) stop(sprintf("Unclosed chunk at line %d", s))
    e <- s + rel_end[[1L]]
    header <- lines[[s]]
    labels[[i]] <- trimws(sub("''^'"\\"'`'"\\"'`'"\\"'`'"\\\\{r[[:space:]]*(["'^,}]*)[,}].*$", "'"\\\\1\", header, perl = TRUE))
    code <- if (e > s + 1L) lines[seq.int(s + 1L, e - 1L)] else character()
    tryCatch(parse(text = code, keep.source = FALSE), error = function(err) stop(sprintf(\"Chunk parse failure line %d label %s: %s\", s, labels[[i]], conditionMessage(err))))
  }
  labels
}
labels <- extract_chunks(docs"'$v2)
if (any(!nzchar(labels))) stop("Empty chunk label")
if (anyDuplicated(labels)) stop("Duplicate chunk label")
extract_inline <- function(lines) {
  txt <- paste(lines, collapse = "'"\\n\")
  hits <- gregexpr(\"\\"'`r[[:space:]]+[''^'"\\"'`'"\\n]+\\"'`", txt, perl = TRUE)
  if (identical(hits[[1L]][1L], -1L)) character() else regmatches(txt, hits)[[1L]]
}
inline_v1 <- extract_inline(docs$v1)
inline_v2 <- extract_inline(docs$v2)
if (!identical(inline_v1, inline_v2)) stop("Inline expressions differ")
abstract_v1 <- docs$v1[grep("''^abstract:", docs$v1)]
abstract_v2 <- docs$v2[grep("''^abstract:", docs$v2)]
if (!identical(abstract_v1, abstract_v2)) stop("Abstract projection differs")
section <- function(lines, start, end) {
  a <- match(start, lines); b <- match(end, lines)
  if (is.na(a) || is.na(b) || b <= a) stop("Section bound missing")
  lines[seq.int(a, b - 1L)]
}
conclusion_v1 <- section(docs$v1, "# Conclusion", "# References {-}")
conclusion_v2 <- section(docs$v2, "# Conclusion", "# References {-}")
if (!identical(conclusion_v1, conclusion_v2)) stop("Conclusion projection differs")
line_v1 <- docs$v1[[338L]]
line_v2 <- docs$v2[[338L]]
prefix <- function(x) strsplit(x, " Appendix Figure", fixed = TRUE)[[1L]][[1L]]
if (!identical(prefix(line_v1), prefix(line_v2))) stop("Line 338 prefix through percentage sentence differs")
cat(sprintf("PASS chunks_parsed_without_evaluation=%d labels_unique=true'"\\n\", length(labels)))
cat(sprintf(\"PASS inline_r_ordered_sequence_identical=true count=%d\\n\", length(inline_v2)))
cat(sprintf(\"PASS abstract_projection_unchanged=true lines=%d\\n\", length(abstract_v2)))
cat(sprintf(\"PASS conclusion_projection_unchanged=true lines=%d bounds=1285-1296\\n\", length(conclusion_v2)))
cat(\"PASS line338_prefix_through_percentage_sentence_byte_identical=true\\n\")
'"

